# Appended to by upload-api (see /vibegis/upload-api/app.py) — every upload
# or table registration adds one LAYER block here. Do not hand-edit while
# the service is running; it locks the file, but a concurrent manual edit
# could still race.

LAYER
  NAME        "upload_admin_units"
  GROUP       "uploads"
  TYPE        POLYGON
  STATUS      ON
  CONNECTIONTYPE POSTGIS
  CONNECTION  "host=postgis dbname=gis user=gis port=5432"
  DATA        "geometry FROM dwh.upload_admin_units USING UNIQUE gid USING SRID=4326"
  PROCESSING  "CLOSE_CONNECTION=DEFER"
  PROJECTION
    "init=epsg:4326"
  END
  METADATA
    "ows_title"         "Admin. units"
    "ows_group_title"   "Eigene Uploads"
    "ows_srs"           "EPSG:4326 EPSG:3857 CRS:84"
    "gml_include_items" "all"
    "ows_keywordlist"   "source:dwh.upload_admin_units,geomtype:polygon"
  END
  CLASSITEM   "POP_DENS_2024"
  CLASS
    NAME "0 – 50"
    EXPRESSION ([POP_DENS_2024] >= 0 AND [POP_DENS_2024] < 50)
    STYLE  COLOR 224 122 95  OUTLINECOLOR 123 67 52  WIDTH 0.6  END
  END
  CLASS
    NAME "50 – 200"
    EXPRESSION ([POP_DENS_2024] >= 50 AND [POP_DENS_2024] < 200)
    STYLE  COLOR 61 153 112  OUTLINECOLOR 33 84 61  WIDTH 0.6  END
  END
  CLASS
    NAME "200 – 500"
    EXPRESSION ([POP_DENS_2024] >= 200 AND [POP_DENS_2024] < 500)
    STYLE  COLOR 91 141 214  OUTLINECOLOR 50 77 117  WIDTH 0.6  END
  END
  CLASS
    NAME "500 – 1000"
    EXPRESSION ([POP_DENS_2024] >= 500 AND [POP_DENS_2024] < 1000)
    STYLE  COLOR 224 176 61  OUTLINECOLOR 123 96 33  WIDTH 0.6  END
  END
  CLASS
    NAME "1000 – 100000000000"
    EXPRESSION ([POP_DENS_2024] >= 1000 AND [POP_DENS_2024] < 100000000000)
    STYLE  COLOR 160 108 213  OUTLINECOLOR 88 59 117  WIDTH 0.6  END
  END
END

